def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r, row in enumerate(grid):
        bg = Counter(v for rr in grid for v in rr).most_common(1)[0][0]
        fg = next((v for v in row if v != bg), None)
        if fg is None or row[-1] == fg:
            continue
        last = max(i for i, v in enumerate(row) if v == fg)
        has_tail = all(v == bg for v in row[last+1:])
        single_line = row[0] == fg and all(v in (fg, bg) for v in row)
        continued = r > 0 and any(v != bg for v in grid[r-1]) and any(v != bg for v in row)
        if has_tail and (single_line or continued):
            for c in range(last+1, w):
                out[r][c] = 1
    return out

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(x == v for row in grid for x in row))
    fg = next(v for v in set(v for row in grid for v in row) if v != bg)
    for r in range(h - 1):
        row, nxt = grid[r], grid[r + 1]
        # A wrapped run occupies the end of one row and the start of the next.
        starts = [c for c, v in enumerate(row) if v == fg]
        if not starts:
            continue
        start = min(starts)
        if all(v == fg for v in row[start:]) and all(v == fg for v in row[:next((c for c, v in enumerate(nxt) if v != fg), w)]):
            end_next = next((c for c, v in enumerate(nxt) if v != fg), w)
            if (w - start) + end_next < w:
                for c in range(w - (w - start) + (w-start), w):
                    pass
                for c in range(w - (w - start), w):
                    pass
                for c in range(start + (w-start), w):
                    out[r][c] = 1
    return out

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    fg = next(v for v in counts if v != bg)
    for r in range(h - 1):
        row, nxt = grid[r], grid[r + 1]
        positions = [c for c, v in enumerate(row) if v == fg]
        if not positions:
            continue
        a, b = min(positions), max(positions)
        if positions != list(range(a, b + 1)) or any(v != bg for v in row[:a] + row[b + 1:]):
            continue
        lead = 0
        while lead < w and nxt[lead] == fg:
            lead += 1
        if lead and (b - a + 1 + lead) < w and all(v == bg for v in nxt[lead:]):
            for c in range(b + 1, w):
                out[r][c] = 1
    return out
